async function main(){
  // 1. Get mails labeled 'complaint'
  const mailsRes = await api.get('/mails', { label: 'complaint' });
  const mails = mailsRes; // assume array
  // 2. Extract unique customer IDs
  const custIds = [...new Set(mails.map(m => m.customer_id).filter(id => id))];
  // 3. For each customer, fetch details and collect tier
  const tierCounts = {};
  for (const id of custIds) {
    const cust = await api.get(`/customers/${id}`);
    const tier = cust.tier || 'unknown';
    tierCounts[tier] = (tierCounts[tier] || 0) + 1;
  }
  return tierCounts;
}
return main();

