async function main(){
  const mailRes = await api.get('/mails', { label: 'complaint' });
  const ids = [...new Set(mailRes.items.map(m=>m.customer_id).filter(Boolean))];
  const tierCounts = {};
  for (const id of ids){
    const cust = await api.get(`/customers/${id}`);
    const tier = cust.tier || 'unknown';
    tierCounts[tier] = (tierCounts[tier]||0)+1;
  }
  return tierCounts;
}
return main();

